def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    if n >= 2 and opp[-1] == 'C' and me[-1] == 'D' and opp[-2] == 'C' and me[-2] == 'D':
        return 'C'

    opp_d = sum(1 for x in opp if x == 'D')
    opp_c = n - opp_d

    if n >= 4:
        if opp_d == 0:
            if n >= 97:
                if n >= 99:
                    return 'D'
                return 'C'
            return 'C'
        if opp_c == 0:
            if rng.random() < 0.02:
                return 'C'
            return 'D'

    recent_n = 8 if n >= 8 else n
    recent_opp = opp[-recent_n:]
    recent_d = sum(1 for x in recent_opp if x == 'D')
    recent_c = recent_n - recent_d

    if recent_d >= 6:
        return 'D'

    if recent_d >= 3:
        if n >= 10 and opp_c * 5 >= n * 3:
            if rng.random() < 0.25:
                return 'C'
        return 'D'

    if recent_d == 2:
        if opp[-1] == 'D':
            if opp[-2] == 'D':
                return 'D'
            return 'D'
        return 'C'

    if recent_d == 1:
        if opp[-1] == 'D':
            if n >= 6:
                prior = opp[-6:-1]
                prior_d = sum(1 for x in prior if x == 'D')
                if prior_d == 0:
                    if rng.random() < 0.5:
                        return 'C'
                    return 'D'
            if n >= 50 and opp_c * 10 >= n * 9:
                if rng.random() < 0.6:
                    return 'C'
                return 'D'
            return 'D'
        return 'C'

    if n >= 90:
        return 'C'

    return 'C'
